function genieTtsUrl(speakText, speakSpeed) {
    var baseUrl = 'http://192.168.1.100:8000';
    var body = JSON.stringify({
        character_name: 'feibi',
        text: String(speakText || ''),
        split_sentence: true
    });
    var option = {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: body
    };
    return baseUrl + '/tts/legado.wav?wait_timeout=300&mode=buffered,' + JSON.stringify(option);
}
